mapper.select:
SELECT
    t.*,
    (SELECT COUNT(1) FROM school_student s WHERE s.school_id = t.school_id AND s.deleted = 0) as school_info_student_count,
    (SELECT COUNT(1) FROM school_teacher t2 WHERE t2.school_id = t.school_id AND t2.deleted = 0) as school_info_teacher_count
FROM (
    SELECT 
    FROM school_info


            AND school_name LIKE CONCAT('%', #{query.schoolName}, '%')


            AND school_code = #{query.schoolCode}


            AND school_type = #{query.schoolType}


            AND school_province = #{query.schoolProvince}


            AND school_city = #{query.schoolCity}


            AND school_education_level = #{query.schoolEducationLevel}


            AND school_is_985 = #{query.schoolIs985}


            AND school_is_211 = #{query.schoolIs211}


            AND school_is_double_first = #{query.schoolIsDoubleFirst}


) t
ORDER BY t.school_create_time DESC
